#!/usr/bin/env bash
set -Eeuo pipefail

# Accept only paths and identifiers generated by the GitHub Actions runner.
stage=${1:?Missing the staging directory.}
deployment_id=${2:?Missing the deployment identifier.}
if [[ ! "$stage" =~ ^/tmp/manager-assets-deploy\.[[:alnum:]]+$ || ! "$deployment_id" =~ ^[a-f0-9]{12}-[0-9]+-[0-9]+$ ]]; then
  echo 'Invalid deployment arguments.' >&2
  exit 1
fi

# Serialize all three repositories while applying code and checking the applications.
exec 9>/var/lock/manager-deploy.lock
flock -w 600 9

# This repository currently versions vendor. Validate that artifact before copying it.
test -s "$stage/composer.json"
test -s "$stage/composer.lock"
test -f "$stage/vendor/autoload.php"
test -f "$stage/.deploy-excludes"
php -r '
require $argv[1];
foreach (["Dompdf\\Dompdf", "PhpOffice\\PhpSpreadsheet\\Spreadsheet", "PHPMailer\\PHPMailer\\PHPMailer"] as $class) {
    if (!class_exists($class)) {
        fwrite(STDERR, "Missing shared dependency: " . $class . PHP_EOL);
        exit(1);
    }
}
echo "Staged shared dependencies loaded successfully." . PHP_EOL;
' "$stage/vendor/autoload.php"

# Preserve replaced and deleted files outside the public web root.
destination=/var/www/izzidoro.com.br/public/manager_assets
backup_directory="/var/backups/manager_assets/$deployment_id"
umask 077
mkdir -p "$backup_directory"
chmod 700 /var/backups/manager_assets "$backup_directory"
rsync --archive --no-owner --no-group --omit-dir-times \
  --chmod=D755,F644 \
  --delay-updates --delete-delay \
  --backup --backup-dir="$backup_directory" \
  --exclude-from="$stage/.deploy-excludes" \
  "$stage/" "$destination/"

# Both applications load these dependencies, so verify both PHP entry points.
echo "Shared files deployed. Backup of replaced files: $backup_directory"
for application in manager manager_main; do
  if ! curl --fail --silent --show-error --output /dev/null \
    --connect-timeout 10 --max-time 30 \
    --retry 2 --retry-delay 3 \
    --resolve izzidoro.com.br:443:127.0.0.1 \
    "https://izzidoro.com.br/$application/public/index.php?url=user/login"; then
    echo "The shared files were uploaded, but the $application health check failed. Check PHP logs." >&2
    exit 1
  fi
done
echo 'Both application health checks passed.'
